GPU_MEM_SIZE = 80 # GB

# EVOLVE-BLOCK-START

def _greedy(gpu_num, sorted_models):
    """Place each model on the GPU whose resulting KVPR is lowest."""
    placement = {i: [] for i in range(gpu_num)}
    free = [GPU_MEM_SIZE] * gpu_num
    load = [0.0] * gpu_num
    for m in sorted_models:
        best_idx, best_kvpr = None, float('inf')
        for g in range(gpu_num):
            if m.model_size <= free[g] and free[g] - m.model_size > 0:
                kvpr = (load[g] + m.req_rate / m.slo) / (free[g] - m.model_size)
                if kvpr < best_kvpr:
                    best_kvpr, best_idx = kvpr, g
        if best_idx is None:
            return None
        placement[best_idx].append(m)
        load[best_idx] += m.req_rate / m.slo
        free[best_idx] -= m.model_size
    return placement


def _greedy_fallback(gpu_num, sorted_models):
    """Fallback: place each model on the GPU with lowest current KVPR that fits."""
    placement = {i: [] for i in range(gpu_num)}
    free = [GPU_MEM_SIZE] * gpu_num
    load = [0.0] * gpu_num
    for m in sorted_models:
        best_idx, best_ratio = None, float('inf')
        for g in range(gpu_num):
            if m.model_size <= free[g] and free[g] > 0:
                ratio = load[g] / free[g]
                if ratio < best_ratio:
                    best_ratio, best_idx = ratio, g
        if best_idx is None:
            return None
        placement[best_idx].append(m)
        load[best_idx] += m.req_rate / m.slo
        free[best_idx] -= m.model_size
    return placement


def _kvpr(mlist):
    """KVPR of a single GPU's model list."""
    free = GPU_MEM_SIZE - sum(m.model_size for m in mlist)
    if not mlist or free <= 0:
        return 0.0
    return sum(m.req_rate / m.slo for m in mlist) / free


def _refine(gpu_num, p):
    """Hill-climb on max KVPR: repeatedly move a model off the worst-KVPR
    GPU whenever doing so lowers the overall max KVPR."""
    k = {g: _kvpr(p[g]) for g in p}
    improved = True
    while improved:
        improved = False
        src = max(p, key=lambda g: k[g])
        for m in list(p[src]):
            for dst in p:
                if dst == src:
                    continue
                dst_free = GPU_MEM_SIZE - sum(x.model_size for x in p[dst])
                if m.model_size > dst_free:
                    continue
                p[src].remove(m)
                p[dst].append(m)
                nk = {g: _kvpr(p[g]) for g in p}
                if max(nk.values()) < max(k.values()) - 1e-12:
                    k = nk
                    improved = True
                    break
                p[dst].remove(m)
                p[src].append(m)
            if improved:
                break
    return p


def compute_model_placement(gpu_num, models):
    """
    Greedy placement minimizing max KVPR: each model goes to the GPU where
    the resulting KVPR is lowest. Multiple model orderings are tried
    (pressure desc, size desc, pressure/size desc), each refined by a
    local-search pass moving models off the worst GPU, and the best
    placement (lowest max KVPR) is returned.
    """
    orders = [
        sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True),
        sorted(models, key=lambda m: m.model_size, reverse=True),
        sorted(models, key=lambda m: (m.req_rate / m.slo) / m.model_size, reverse=True),
    ]
    best, best_max = None, float('inf')
    for ms in orders:
        p = _greedy(gpu_num, ms)
        if p is None:
            continue
        p = _refine(gpu_num, p)
        mx = max(_kvpr(mlist) for mlist in p.values())
        if mx < best_max:
            best, best_max = p, mx
    if best is None:
        for ms in orders:
            p = _greedy_fallback(gpu_num, ms)
            if p is not None:
                p = _refine(gpu_num, p)
                mx = max(_kvpr(mlist) for mlist in p.values())
                if mx < best_max:
                    best, best_max = p, mx
    if best is None:
        raise ValueError("Unable to place all models within GPU memory")
    return best

